package com.attendance;
import java.util.*;import java.time.LocalDate;import java.time.LocalTime;import java.time.Duration;import java.nio.charset.StandardCharsets;import java.nio.file.*;import javax.imageio.ImageIO;import javax.imageio.stream.ImageInputStream;import java.awt.image.BufferedImage;import java.io.ByteArrayInputStream;import java.io.ByteArrayOutputStream;
import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.core.Authentication;import org.springframework.util.LinkedMultiValueMap;import org.springframework.core.io.ByteArrayResource;import org.springframework.web.client.RestClient;
@RestController @RequestMapping("/api") public class Api {
 final JdbcTemplate db; final StudentConsentService consentService; final Path photoRoot=Paths.get(System.getenv().getOrDefault("ENROLLMENT_PHOTO_DIR","./data/enrollment-photos")); Api(JdbcTemplate db,StudentConsentService consentService){this.db=db;this.consentService=consentService;}
 static final java.util.logging.Logger LOG=java.util.logging.Logger.getLogger(Api.class.getName());
 void check(boolean b,String m){if(!b)throw new ResponseStatusException(HttpStatus.CONFLICT,m);}
 boolean admin(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));}
 void adminOnly(Authentication a){if(!admin(a))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
 Map<String,Object> course(UUID id,Authentication a){var c=db.queryForMap("select * from courses where id=?",id);if(!admin(a)&&!Objects.equals(c.get("teacher"),a.getName()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return c;}
 Map<String,Object> session(UUID id,Authentication a){
  var s=db.queryForMap("select s.*,c.name,c.course_code,o.academic_term,o.academic_year,o.batch,o.section,o.legacy as legacy_offering,p.display_name as teacher_name,p.username as teacher_username,c.course_code || ' — ' || o.academic_term || case when o.academic_year is null then '' else ' ' || o.academic_year end || ' — Batch ' || o.batch || ' — Section ' || o.section as offering_label from sessions s join courses c on c.id=s.course_id join course_offerings o on o.id=s.offering_id left join teacher_profiles p on p.id=s.teacher_profile_id where s.id=? for update of s",id);
  if(!admin(a)){
   UUID teacher=db.query("select id from teacher_profiles where username=? and active=true",rs->rs.next()?UUID.fromString(rs.getString(1)):null,a.getName());
   check(teacher!=null,"No active teacher profile is linked to this account");
   boolean owner=Objects.equals(teacher,s.get("teacher_profile_id"));
   boolean assigned=db.queryForObject("select count(*)>0 from teacher_assignments where offering_id=? and teacher_id=? and not legacy and effective_from<=? and (effective_to is null or effective_to>=?)",Boolean.class,s.get("offering_id"),teacher,s.get("class_date"),s.get("class_date"));
   boolean substitute=db.queryForObject("select count(*)>0 from session_substitute_authorizations where session_id=? and teacher_id=? and revoked_at is null",Boolean.class,id,teacher);
   boolean historical=s.get("status").equals("FINALIZED")&&owner;
   if(!historical&&!((owner&&assigned)||substitute))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Session is not assigned to this teacher");
  }
  return s;
 }
 void draft(Map<String,Object>s){check(!s.get("status").equals("FINALIZED"),"Session already finalized");}
 void audit(UUID id,Authentication a,String action){db.update("insert into audit(session_id,actor,action) values(?,?,?)",id,a.getName(),action);}
 void adminDeletion(String type,UUID id,Authentication a,String action){db.update("insert into administrative_deletions(entity_type,entity_id,actor,action) values(?,?,?,?)",type,id,a.getName(),action);}
 @GetMapping("/me") Object me(Authentication a){
  if(admin(a))return Map.of("username",a.getName(),"admin",true,"student",false,"role","ADMIN","mustChangePassword",false);
  var account=db.queryForList("select a.student_id,a.must_change_password,s.name,s.roll from student_accounts a join students s on s.id=a.student_id where lower(a.username)=lower(?) and a.active=true and a.account_status='APPROVED' and s.archived=false",a.getName());
  if(!account.isEmpty()){var row=account.get(0);return Map.of("username",a.getName(),"admin",false,"student",true,"role","STUDENT","studentId",row.get("student_id"),"name",row.get("name"),"roll",row.get("roll"),"mustChangePassword",row.get("must_change_password"));}
  return Map.of("username",a.getName(),"admin",false,"student",false,"role","TEACHER","mustChangePassword",false);
 }
 @GetMapping("/students") Object students(Authentication a){adminOnly(a);var rows=db.queryForList("select s.*, (select count(*) from attendance x where x.student_id=s.id) as attendance_count, e.id as enrollment_id, e.accepted_photo_count, e.created_at as enrollment_date,case when e.id is not null then 'ENROLLED' when p.id is not null then 'PENDING_REVIEW' else 'NOT_ENROLLED' end as enrollment_status, p.id as pending_enrollment_id,p.rejection_reason as face_rejection_reason, account.username as account_username,account.active as account_active,account.account_status,account.must_change_password,account.registration_source from students s left join student_enrollments e on e.student_id=s.id and e.status='ACTIVE' left join student_enrollments p on p.student_id=s.id and p.status='PENDING_REVIEW' left join student_accounts account on account.student_id=s.id order by s.archived, s.roll");for(var row:rows)if("NOT_ENROLLED".equals(row.get("enrollment_status"))&&Boolean.TRUE.equals(row.get("consent"))){try{var exists=ai().get().uri("/enroll/"+row.get("id")+"/exists").retrieve().body(Map.class);if(Boolean.TRUE.equals(exists.get("enrolled")))row.put("enrollment_status","ENROLLED_PHOTOS_UNAVAILABLE");}catch(Exception ignored){}}return rows;}
 record Student(String name,String roll,boolean consent){}
 @PostMapping("/students") Object student(@RequestBody Student x,Authentication a){adminOnly(a);check(x.name()!=null&&!x.name().isBlank()&&x.roll()!=null&&!x.roll().isBlank(),"Name and roll required");UUID id=UUID.randomUUID();db.update("insert into students(id,name,roll,consent,consent_updated_at,consent_source) values(?,?,?,?,case when ? then now() else null end,case when ? then 'ADMIN' else null end)",id,x.name().trim(),x.roll().trim(),x.consent(),x.consent(),x.consent());return Map.of("id",id);}
 @Transactional @DeleteMapping("/students/{id}") Object deleteStudent(@PathVariable UUID id,Authentication a)throws Exception{adminOnly(a);var s=db.queryForMap("select * from students where id=? for update",id);check(!Boolean.TRUE.equals(s.get("archived")),"Student is already archived");ai().delete().uri("/enroll/"+id).retrieve().toBodilessEntity();int history=db.queryForObject("select count(*) from attendance where student_id=?",Integer.class,id);deleteStoredPhotos(id);db.update("delete from enrollment_photos where enrollment_id in (select id from student_enrollments where student_id=?)",id);db.update("delete from student_photo_submission_audit where student_id=?",id);db.update("delete from student_enrollments where student_id=?",id);db.update("delete from enrollments where student_id=?",id);if(history>0){db.update("update offering_enrollments set status='ENDED',active_to=current_date where student_id=? and status='ACTIVE'",id);db.update("update students set archived=true,consent=false,consent_updated_at=now(),consent_source='ADMIN_ARCHIVE' where id=?",id);db.update("update student_accounts set active=false,account_status='DEACTIVATED',updated_at=now() where student_id=?",id);adminDeletion("STUDENT",id,a,"ARCHIVED");return Map.of("archived",true);}db.update("delete from offering_enrollment_audit where student_id=?",id);db.update("delete from offering_enrollments where student_id=?",id);db.update("update student_registration_requests set candidate_student_id=null,student_id=null,password_hash='!',status_token_hash='!',full_name='[deleted student]',normalized_roll='DELETED-'||id::text,email='deleted+'||id::text||'@invalid.local',normalized_email='deleted+'||id::text||'@invalid.local',username='deleted-'||id::text,normalized_username='deleted-'||id::text where candidate_student_id=? or student_id=?",id,id);db.update("delete from student_accounts where student_id=?",id);db.update("delete from students where id=?",id);adminDeletion("STUDENT",id,a,"DELETED");return Map.of("deleted",true);}
 @GetMapping("/courses") Object courses(Authentication a){String sql="select c.*,(select count(*) from offering_enrollments e join course_offerings o on o.id=e.offering_id join students s on s.id=e.student_id where o.course_id=c.id and o.legacy and e.status='ACTIVE' and s.archived=false) as enrolled_count,(select count(*) from sessions s where s.course_id=c.id) as session_count from courses c where c.archived=false "+(admin(a)?"":"and c.teacher=? ")+"order by c.name";return admin(a)?db.queryForList(sql):db.queryForList(sql,a.getName());}
 record Course(String name,String teacher){}
 @Transactional @PostMapping("/courses") Object addCourse(@RequestBody Course x,Authentication a){adminOnly(a);check(x.name()!=null&&!x.name().isBlank()&&Set.of("admin","teacher").contains(x.teacher()),"Valid name and teacher required");UUID id=UUID.randomUUID(),offering=UUID.randomUUID();String code="LEGACY-"+id.toString().replace("-","").toUpperCase(Locale.ROOT);db.update("insert into courses(id,name,teacher,course_code) values(?,?,?,?)",id,x.name(),x.teacher(),code);db.update("insert into course_offerings(id,course_id,academic_term,batch,section,legacy) values(?,?,'Legacy (unknown)','Legacy (unknown)','Legacy (unknown)',true)",offering,id);UUID profile=db.queryForObject("select id from teacher_profiles where username=?",UUID.class,x.teacher());db.update("insert into teacher_assignments(id,offering_id,teacher_id,assignment_role,legacy,created_by) values(?,?,?,'PRIMARY',true,?)",UUID.randomUUID(),offering,profile,a.getName());return Map.of("id",id);}
 @Transactional @DeleteMapping("/courses/{id}") Object deleteCourse(@PathVariable UUID id,Authentication a){adminOnly(a);var c=db.queryForMap("select * from courses where id=? for update",id);check(!Boolean.TRUE.equals(c.get("archived")),"Course is already archived");check(db.queryForObject("select count(*) from sessions where course_id=?",Integer.class,id)==0,"Course has sessions; archive it instead.");db.update("delete from enrollments where course_id=?",id);db.update("delete from courses where id=?",id);adminDeletion("COURSE",id,a,"DELETED");return Map.of("deleted",true);}
 @Transactional @PostMapping("/courses/{id}/archive") Object archiveCourse(@PathVariable UUID id,Authentication a){adminOnly(a);db.queryForMap("select * from courses where id=? for update",id);db.update("update courses set archived=true where id=?",id);adminDeletion("COURSE",id,a,"ARCHIVED");return Map.of("archived",true);}
 @GetMapping("/courses/{id}/students") Object roster(@PathVariable UUID id,Authentication a){course(id,a);return db.queryForList("select s.* from students s join offering_enrollments e on e.student_id=s.id join course_offerings o on o.id=e.offering_id where o.course_id=? and o.legacy and e.status='ACTIVE' order by s.roll",id);}
 @Transactional @PostMapping("/courses/{id}/students/{student}") void enroll(@PathVariable UUID id,@PathVariable UUID student,Authentication a){adminOnly(a);check(db.queryForObject("select count(*) from courses where id=? and archived=false",Integer.class,id)==1,"Course not found or archived");check(db.queryForObject("select count(*) from students where id=? and archived=false",Integer.class,student)==1,"Student not found or archived");var legacy=db.queryForList("select id from course_offerings where course_id=? and legacy=true",UUID.class,id);check(!legacy.isEmpty(),"Legacy offering not found");db.update("insert into offering_enrollments(id,offering_id,student_id,status,active_from,source,created_by) values(?,?,?,'ACTIVE',?,'ADMIN',?) on conflict do nothing",UUID.randomUUID(),legacy.get(0),student,java.time.LocalDate.now(java.time.ZoneId.of("Asia/Dhaka")),a.getName());db.update("insert into offering_enrollment_audit(offering_id,student_id,actor,action) values(?,?,?,'ENROLLED') on conflict do nothing",legacy.get(0),student,a.getName());db.update("insert into enrollments values(?,?) on conflict do nothing",id,student);}
 @PostMapping("/students/{id}/faces") @Transactional Object faces(@PathVariable UUID id,@RequestParam("images") List<MultipartFile> files,Authentication a)throws Exception{
  adminOnly(a);check(Boolean.TRUE.equals(db.queryForObject("select consent from students where id=? and archived=false",Boolean.class,id)),"Verified consent is required");
  check(files.size()>=5&&files.size()<=10,"Require 5–10 photos");
  check(db.queryForObject("select count(*) from student_enrollments where student_id=? and status='PENDING_REVIEW'",Integer.class,id)==0,"Review or cancel the pending student photo submission first");
  UUID enrollment=UUID.randomUUID();var body=new LinkedMultiValueMap<String,Object>();for(var f:files){validateImage(f);body.add("images",resource(f));}
  try{
   ai().post().uri(u->u.path("/enroll/"+id).queryParam("version",enrollment).build()).contentType(MediaType.MULTIPART_FORM_DATA).body(body).retrieve().toBodilessEntity();
   Files.createDirectories(photoRoot.resolve(enrollment.toString()));List<StoredPhoto>stored=new ArrayList<>();for(int i=0;i<files.size();i++)stored.add(storePhoto(enrollment,i,files.get(i)));
   db.update("update student_enrollments set status='RETIRED',retention_until=now()+interval '90 days',embedding_cleanup_pending=true where student_id=? and status='ACTIVE'",id);
   db.update("insert into student_enrollments(id,student_id,status,accepted_photo_count,created_by,activated_at,submission_source,reviewed_by,reviewed_at) values(?,?,'ACTIVE',?,?,now(),'ADMIN',?,now())",enrollment,id,files.size(),a.getName(),a.getName());
   for(var photo:stored)db.update("insert into enrollment_photos(id,enrollment_id,storage_key,thumbnail_key,photo_index,width,height) values(?,?,?,?,?,?,?)",photo.id(),enrollment,photo.key(),photo.thumb(),photo.index(),photo.width(),photo.height());
   ai().post().uri(u->u.path("/enroll/"+id+"/activate").queryParam("version",enrollment).build()).retrieve().toBodilessEntity();
   db.update("insert into student_photo_submission_audit(enrollment_id,student_id,actor,action,reason) values(?,?,?,'APPROVED','Admin verified identity and recorded consent')",enrollment,id,a.getName());
   return Map.of("enrollmentId",enrollment,"acceptedPhotoCount",files.size(),"status","ACTIVE");
  }catch(Exception exception){
   try{ai().delete().uri(u->u.path("/enroll/"+id).queryParam("version",enrollment).build()).retrieve().toBodilessEntity();}
   catch(Exception cleanup){LOG.severe("Failed to clean staged admin embedding "+enrollment+": "+cleanup.getMessage());}
   deleteEnrollmentFiles(enrollment);throw exception;
  }
 }
 record StoredPhoto(UUID id,String key,String thumb,int index,int width,int height){}
 void deleteStoredPhotos(UUID student)throws Exception{for(var p:db.queryForList("select storage_key,thumbnail_key from enrollment_photos p join student_enrollments e on e.id=p.enrollment_id where e.student_id=?",student)){Files.deleteIfExists(photoRoot.resolve((String)p.get("storage_key")));Files.deleteIfExists(photoRoot.resolve((String)p.get("thumbnail_key")));}}
 void deleteEnrollmentFiles(UUID enrollment)throws Exception{if(Files.exists(photoRoot.resolve(enrollment.toString())))try(var paths=Files.walk(photoRoot.resolve(enrollment.toString()))){paths.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.deleteIfExists(p);}catch(Exception ignored){}});}}
 void validateImage(MultipartFile f)throws Exception{check(f.getSize()>0&&f.getSize()<=10485760,"Image must be 1–10 MB");byte[] bytes=f.getBytes();try(ImageInputStream stream=ImageIO.createImageInputStream(new ByteArrayInputStream(bytes))){Iterator<javax.imageio.ImageReader> readers=ImageIO.getImageReaders(stream);check(readers.hasNext(),"Use a valid JPEG or PNG image");var reader=readers.next();try{String format=reader.getFormatName();check(format.equalsIgnoreCase("JPEG")||format.equalsIgnoreCase("PNG"),"Use a JPEG or PNG image");reader.setInput(stream);long pixels=(long)reader.getWidth(0)*reader.getHeight(0);check(pixels<=24000000,"Image dimensions must not exceed 24 megapixels");BufferedImage im=reader.read(0);check(im!=null&&im.getWidth()>=30&&im.getHeight()>=30,"Image is too small");}finally{reader.dispose();}}}
 StoredPhoto storePhoto(UUID enrollment,int index,MultipartFile file)throws Exception{BufferedImage im=ImageIO.read(new ByteArrayInputStream(file.getBytes()));UUID id=UUID.randomUUID();String key=enrollment+"/"+id+".jpg",thumb=enrollment+"/"+id+"-thumb.jpg";Path full=photoRoot.resolve(key),small=photoRoot.resolve(thumb);Files.createDirectories(full.getParent());ImageIO.write(im,"jpg",full.toFile());BufferedImage t=new BufferedImage(Math.min(320,im.getWidth()),Math.max(1,Math.min(320,im.getWidth())*im.getHeight()/im.getWidth()),BufferedImage.TYPE_INT_RGB);var g=t.createGraphics();g.drawImage(im,0,0,t.getWidth(),t.getHeight(),null);g.dispose();ImageIO.write(t,"jpg",small.toFile());return new StoredPhoto(id,key,thumb,index,im.getWidth(),im.getHeight());}
 @GetMapping("/students/{id}/faces") Object facePhotos(@PathVariable UUID id,@RequestParam UUID enrollmentId,Authentication a){adminOnly(a);return db.queryForList("select p.id,p.enrollment_id,p.photo_index,p.width,p.height from enrollment_photos p join student_enrollments e on e.id=p.enrollment_id where e.student_id=? and e.id=? and e.status='ACTIVE' order by p.photo_index",id,enrollmentId);}
 @GetMapping("/students/{student}/faces/{photo}") ResponseEntity<byte[]> face(@PathVariable UUID student,@PathVariable UUID photo,@RequestParam UUID enrollmentId,Authentication a)throws Exception{return image(student,enrollmentId,photo,false,a);}
 @GetMapping("/students/{student}/faces/{photo}/thumbnail") ResponseEntity<byte[]> thumb(@PathVariable UUID student,@PathVariable UUID photo,@RequestParam UUID enrollmentId,Authentication a)throws Exception{return image(student,enrollmentId,photo,true,a);}
 ResponseEntity<byte[]> image(UUID student,UUID enrollmentId,UUID photo,boolean thumbnail,Authentication a)throws Exception{adminOnly(a);var keys=db.queryForList("select p."+(thumbnail?"thumbnail_key":"storage_key")+" from enrollment_photos p join student_enrollments e on e.id=p.enrollment_id where p.id=? and e.id=? and e.student_id=? and e.status='ACTIVE'",String.class,photo,enrollmentId,student);if(keys.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Enrollment photo not found");return ResponseEntity.ok().cacheControl(org.springframework.http.CacheControl.noStore()).contentType(MediaType.IMAGE_JPEG).body(Files.readAllBytes(photoRoot.resolve(keys.get(0))));}
 @DeleteMapping("/students/{id}/faces") @Transactional void deleteFaces(@PathVariable UUID id,Authentication a)throws Exception{adminOnly(a);ai().delete().uri("/enroll/"+id).retrieve().toBodilessEntity();deleteStoredPhotos(id);db.update("delete from enrollment_photos where enrollment_id in (select id from student_enrollments where student_id=?)",id);db.update("delete from student_enrollments where student_id=?",id);db.update("update students set consent=false where id=?",id);}
 UUID activeStudentId(Authentication authentication){return db.query("select a.student_id from student_accounts a join students s on s.id=a.student_id where lower(a.username)=lower(?) and a.active=true and a.account_status='APPROVED' and s.archived=false",rs->rs.next()?rs.getObject(1,UUID.class):null,authentication.getName());}
 @PostMapping("/student/faces") @Transactional Object studentFaceSubmission(@RequestParam("images")List<MultipartFile>files,@RequestParam boolean consent,Authentication a)throws Exception{
  UUID student=activeStudentId(a);if(student==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"An active approved student account is required");
  db.queryForMap("select id from students where id=? and archived=false for update",student);
  check(consent,"Explicit biometric consent is required to submit face photos");check(files.size()>=5&&files.size()<=10,"Require 5–10 photos");
  if(db.queryForObject("select count(*) from student_enrollments where student_id=? and status='PENDING_REVIEW'",Integer.class,student)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"A face-photo submission is already pending review");
  for(var file:files)validateImage(file);
  UUID enrollment=UUID.randomUUID();var body=new LinkedMultiValueMap<String,Object>();for(var file:files)body.add("images",resource(file));
  db.update("update students set consent=true,consent_updated_at=now(),consent_source='STUDENT' where id=? and archived=false",student);
  try{
   ai().post().uri(u->u.path("/enroll/"+student).queryParam("version",enrollment).build()).contentType(MediaType.MULTIPART_FORM_DATA).body(body).retrieve().toBodilessEntity();
   Files.createDirectories(photoRoot.resolve(enrollment.toString()));List<StoredPhoto>stored=new ArrayList<>();for(int i=0;i<files.size();i++)stored.add(storePhoto(enrollment,i,files.get(i)));
   db.update("insert into student_enrollments(id,student_id,status,accepted_photo_count,created_by,submission_source) values(?,?,'PENDING_REVIEW',?,?,'SELF_REGISTRATION')",enrollment,student,files.size(),a.getName());
   for(var photo:stored)db.update("insert into enrollment_photos(id,enrollment_id,storage_key,thumbnail_key,photo_index,width,height) values(?,?,?,?,?,?,?)",photo.id(),enrollment,photo.key(),photo.thumb(),photo.index(),photo.width(),photo.height());
   db.update("insert into student_photo_submission_audit(enrollment_id,student_id,actor,action) values(?,?,?,'SUBMITTED')",enrollment,student,a.getName());
   return Map.of("enrollmentId",enrollment,"status","PENDING_REVIEW","acceptedPhotoCount",files.size());
  }catch(Exception exception){try{ai().delete().uri(u->u.path("/enroll/"+student).queryParam("version",enrollment).build()).retrieve().toBodilessEntity();}catch(Exception cleanup){LOG.severe("Failed to remove staged embedding "+enrollment+": "+cleanup.getMessage());}deleteEnrollmentFiles(enrollment);throw exception;}
 }
 @GetMapping("/student/faces") Object studentFaceSubmissions(Authentication a){UUID student=activeStudentId(a);if(student==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"An active approved student account is required");return db.queryForList("select id,status,accepted_photo_count,rejection_reason,created_at,reviewed_at,retention_until from student_enrollments where student_id=? and status in ('ACTIVE','PENDING_REVIEW','REJECTED','CANCELLED') order by created_at desc",student);}
 @GetMapping("/student/faces/{enrollment}/photos") Object studentFacePhotoList(@PathVariable UUID enrollment,Authentication a){UUID student=activeStudentId(a);if(student==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN);return db.queryForList("select p.id,p.enrollment_id,p.photo_index,p.width,p.height from enrollment_photos p join student_enrollments e on e.id=p.enrollment_id where e.student_id=? and e.id=? and e.status in ('ACTIVE','PENDING_REVIEW') order by p.photo_index",student,enrollment);}
 @GetMapping("/student/faces/{enrollment}/photos/{photo}") ResponseEntity<byte[]> studentFacePhoto(@PathVariable UUID enrollment,@PathVariable UUID photo,Authentication a)throws Exception{UUID student=activeStudentId(a);if(student==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN);return enrollmentImage(student,enrollment,photo,false);}
 @GetMapping("/student/faces/{enrollment}/photos/{photo}/thumbnail") ResponseEntity<byte[]> studentFacePhotoThumbnail(@PathVariable UUID enrollment,@PathVariable UUID photo,Authentication a)throws Exception{UUID student=activeStudentId(a);if(student==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN);return enrollmentImage(student,enrollment,photo,true);}
 ResponseEntity<byte[]> enrollmentImage(UUID student,UUID enrollment,UUID photo,boolean thumbnail)throws Exception{
  List<String>keys=db.query("select p."+(thumbnail?"thumbnail_key":"storage_key")+" from enrollment_photos p join student_enrollments e on e.id=p.enrollment_id where p.id=? and e.id=? and e.student_id=? and e.status in ('ACTIVE','PENDING_REVIEW')", (rs,row)->rs.getString(1),photo,enrollment,student);
  if(keys.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Enrollment photo not found");
  Path root=photoRoot.toAbsolutePath().normalize(),path=root.resolve(keys.get(0)).normalize();if(!path.startsWith(root))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Enrollment photo not found");
  return ResponseEntity.ok().cacheControl(org.springframework.http.CacheControl.noStore()).contentType(MediaType.IMAGE_JPEG).body(Files.readAllBytes(path));
 }
 record FaceRejection(String reason){}
 @GetMapping("/admin/face-submissions") Object pendingFaceSubmissions(Authentication a){adminOnly(a);return db.queryForList("select e.id as enrollment_id,e.student_id,s.name,s.roll,s.email,e.accepted_photo_count,e.created_at,e.submission_source from student_enrollments e join students s on s.id=e.student_id where e.status='PENDING_REVIEW' order by e.created_at");}
 @GetMapping("/admin/face-submissions/{enrollment}/photos") Object reviewFacePhotos(@PathVariable UUID enrollment,Authentication a){adminOnly(a);return db.queryForList("select p.id,p.enrollment_id,p.photo_index,p.width,p.height from enrollment_photos p join student_enrollments e on e.id=p.enrollment_id where e.id=? and e.status='PENDING_REVIEW' order by p.photo_index",enrollment);}
 @GetMapping("/admin/face-submissions/{enrollment}/photos/{photo}") ResponseEntity<byte[]> reviewFacePhoto(@PathVariable UUID enrollment,@PathVariable UUID photo,Authentication a)throws Exception{adminOnly(a);UUID student=db.query("select student_id from student_enrollments where id=? and status='PENDING_REVIEW'",rs->rs.next()?rs.getObject(1,UUID.class):null,enrollment);if(student==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Pending face submission not found");return enrollmentImage(student,enrollment,photo,false);}
 @GetMapping("/admin/face-submissions/{enrollment}/photos/{photo}/thumbnail") ResponseEntity<byte[]> reviewFacePhotoThumbnail(@PathVariable UUID enrollment,@PathVariable UUID photo,Authentication a)throws Exception{adminOnly(a);UUID student=db.query("select student_id from student_enrollments where id=? and status='PENDING_REVIEW'",rs->rs.next()?rs.getObject(1,UUID.class):null,enrollment);if(student==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Pending face submission not found");return enrollmentImage(student,enrollment,photo,true);}
 @PostMapping("/admin/face-submissions/{enrollment}/approve") @Transactional Object approveFaceSubmission(@PathVariable UUID enrollment,Authentication a){
  adminOnly(a);var row=db.queryForMap("select e.student_id,e.status,s.consent,s.archived from student_enrollments e join students s on s.id=e.student_id where e.id=? for update of e,s",enrollment);
  if("ACTIVE".equals(row.get("status")))return Map.of("status","ACTIVE");
  check("PENDING_REVIEW".equals(row.get("status")),"Only pending face submissions can be approved");
  check(Boolean.TRUE.equals(row.get("consent"))&&!Boolean.TRUE.equals(row.get("archived")),"Active consent and student profile are required");
  UUID student=(UUID)row.get("student_id");check(db.queryForObject("select count(*) from student_accounts where student_id=? and active=true and account_status='APPROVED'",Integer.class,student)==1,"Student account must be approved and active");
  db.update("update student_enrollments set status='RETIRED',retention_until=now()+interval '90 days',embedding_cleanup_pending=true where student_id=? and status='ACTIVE'",student);
  db.update("update student_enrollments set status='ACTIVE',reviewed_by=?,reviewed_at=now(),retention_until=null,embedding_cleanup_pending=false where id=?",a.getName(),enrollment);
  try{ai().post().uri(u->u.path("/enroll/"+student+"/activate").queryParam("version",enrollment).build()).retrieve().toBodilessEntity();}
  catch(Exception exception){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Embedding activation failed; the prior enrollment remains active. Retry approval after checking the AI service.");}
  db.update("insert into student_photo_submission_audit(enrollment_id,student_id,actor,action) values(?,?,?,'APPROVED')",enrollment,student,a.getName());
  return Map.of("status","ACTIVE");
 }
 @PostMapping("/admin/face-submissions/{enrollment}/reject") @Transactional Object rejectFaceSubmission(@PathVariable UUID enrollment,@RequestBody FaceRejection decision,Authentication a){
  adminOnly(a);if(decision.reason()==null||decision.reason().isBlank()||decision.reason().trim().length()<5||decision.reason().trim().length()>1000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A rejection reason of 5–1000 characters is required");
  var row=db.queryForMap("select student_id,status from student_enrollments where id=? for update",enrollment);if("REJECTED".equals(row.get("status")))return Map.of("status","REJECTED","cleanupPending",Boolean.TRUE.equals(db.queryForObject("select embedding_cleanup_pending from student_enrollments where id=?",Boolean.class,enrollment)));
  check("PENDING_REVIEW".equals(row.get("status")),"Only pending face submissions can be rejected");UUID student=(UUID)row.get("student_id");
  db.update("update student_enrollments set status='REJECTED',rejection_reason=?,reviewed_by=?,reviewed_at=now(),retention_until=now()+interval '90 days',embedding_cleanup_pending=true where id=?",decision.reason().trim(),a.getName(),enrollment);
  db.update("insert into student_photo_submission_audit(enrollment_id,student_id,actor,action,reason) values(?,?,?,'REJECTED',?)",enrollment,student,a.getName(),decision.reason().trim());
  boolean cleanupPending=true;try{ai().delete().uri(u->u.path("/enroll/"+student).queryParam("version",enrollment).build()).retrieve().toBodilessEntity();db.update("update student_enrollments set embedding_cleanup_pending=false where id=?",enrollment);cleanupPending=false;}catch(Exception exception){LOG.severe("Rejected face embedding cleanup pending for "+enrollment+": "+exception.getMessage());}
  return Map.of("status","REJECTED","cleanupPending",cleanupPending,"message",cleanupPending?"Rejected; staged embedding cleanup will be retried.":"Rejected and staged embedding removed.");
 }
 @DeleteMapping("/student/faces/{enrollment}") @Transactional Object cancelFaceSubmission(@PathVariable UUID enrollment,Authentication a){
  UUID student=activeStudentId(a);if(student==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN);
  int updated=db.update("update student_enrollments set status='CANCELLED',reviewed_by=?,reviewed_at=now(),retention_until=now()+interval '90 days',embedding_cleanup_pending=true where id=? and student_id=? and status='PENDING_REVIEW'",a.getName(),enrollment,student);
  if(updated!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only your pending face submission can be cancelled");
  db.update("insert into student_photo_submission_audit(enrollment_id,student_id,actor,action) values(?,?,?,'CANCELLED')",enrollment,student,a.getName());
  boolean cleanupPending=true;try{ai().delete().uri(u->u.path("/enroll/"+student).queryParam("version",enrollment).build()).retrieve().toBodilessEntity();db.update("update student_enrollments set embedding_cleanup_pending=false where id=?",enrollment);cleanupPending=false;}catch(Exception exception){LOG.severe("Cancelled face embedding cleanup pending for "+enrollment+": "+exception.getMessage());}
  return Map.of("status","CANCELLED","cleanupPending",cleanupPending);
 }
 @DeleteMapping("/student/consent") Object withdrawStudentConsent(Authentication a){
  UUID student=activeStudentId(a);if(student==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN);
  consentService.withdraw(student,a.getName());
  try{ai().delete().uri("/enroll/"+student).retrieve().toBodilessEntity();db.update("update student_enrollments set embedding_cleanup_pending=false where student_id=? and status in ('RETIRED','REJECTED','CANCELLED')",student);return Map.of("consent",false,"cleanupPending",false);}
  catch(Exception exception){LOG.severe("Consent withdrawal embedding cleanup pending for "+student+": "+exception.getMessage());throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Consent was withdrawn immediately, so recognition is blocked. Embedding deletion failed and will be retried.");}
 }
 @GetMapping("/sessions") Object sessions(Authentication a){if(admin(a))return db.queryForList("select s.*,c.name,c.course_code,o.academic_term,o.academic_year,o.batch,o.section,p.display_name as teacher_name,c.course_code || ' — ' || o.academic_term || case when o.academic_year is null then '' else ' ' || o.academic_year end || ' — Batch ' || o.batch || ' — Section ' || o.section as offering_label from sessions s join courses c on c.id=s.course_id join course_offerings o on o.id=s.offering_id left join teacher_profiles p on p.id=s.teacher_profile_id order by s.class_date desc,s.class_start_time desc nulls last");return db.queryForList("select s.*,c.name,c.course_code,o.academic_term,o.academic_year,o.batch,o.section,p.display_name as teacher_name,c.course_code || ' — ' || o.academic_term || case when o.academic_year is null then '' else ' ' || o.academic_year end || ' — Batch ' || o.batch || ' — Section ' || o.section as offering_label from sessions s join courses c on c.id=s.course_id join course_offerings o on o.id=s.offering_id left join teacher_profiles p on p.id=s.teacher_profile_id where s.teacher_profile_id=(select id from teacher_profiles where username=? and active=true) or exists(select 1 from session_substitute_authorizations x join teacher_profiles t on t.id=x.teacher_id where x.session_id=s.id and t.username=? and x.revoked_at is null) order by s.class_date desc,s.class_start_time desc nulls last",a.getName(),a.getName());}
 record NewSession(UUID courseId,UUID offeringId,UUID teacherId,boolean authorizeSubstitute,LocalDate date,LocalTime startTime,LocalTime endTime){}
 @PostMapping("/sessions") @Transactional Object create(@RequestBody NewSession x,Authentication a){
  check(x.date()!=null&&x.startTime()!=null&&x.endTime()!=null,"Class date, start time, and end time are required");
  check(x.endTime().isAfter(x.startTime()),"Class end time must be later than start time");
  UUID offeringId=x.offeringId();
  if(offeringId==null&&x.courseId()!=null){var legacy=db.queryForList("select id from course_offerings where course_id=? and legacy=true",UUID.class,x.courseId());check(!legacy.isEmpty(),"Legacy offering not found");offeringId=legacy.get(0);}
  check(offeringId!=null,"Select a course offering");
  var offers=db.queryForList("select o.id,o.course_id,o.archived,c.archived as course_archived from course_offerings o join courses c on c.id=o.course_id where o.id=? for update of o",offeringId);
  check(!offers.isEmpty(),"Offering not found");var offering=offers.get(0);
  check(!Boolean.TRUE.equals(offering.get("archived"))&&!Boolean.TRUE.equals(offering.get("course_archived")),"Offering or course is archived");
  UUID actualTeacher=x.teacherId();boolean makeSubstitute=false;
  if(!admin(a)){
   UUID self=db.query("select id from teacher_profiles where username=? and active=true",rs->rs.next()?UUID.fromString(rs.getString(1)):null,a.getName());
   check(self!=null,"No active teacher profile is linked to this account");
   check(actualTeacher==null||actualTeacher.equals(self),"Teachers cannot select another teacher");
   check(!x.authorizeSubstitute(),"Only an administrator can authorize a substitute");actualTeacher=self;
   check(db.queryForObject("select count(*) from teacher_assignments where offering_id=? and teacher_id=? and not legacy and effective_from<=? and (effective_to is null or effective_to>=?) and effective_from<=current_date and (effective_to is null or effective_to>=current_date)",Integer.class,offeringId,self,x.date(),x.date())>0,"An active offering assignment is required to create this session");
  }else{
   if(actualTeacher==null)actualTeacher=db.query("select a.teacher_id from teacher_assignments a where a.offering_id=? and a.assignment_role='PRIMARY' and not a.legacy and a.effective_from<=? and (a.effective_to is null or a.effective_to>=?) and a.effective_from<=current_date and (a.effective_to is null or a.effective_to>=current_date) order by a.effective_from desc limit 1",rs->rs.next()?UUID.fromString(rs.getString(1)):null,offeringId,x.date(),x.date());
   check(actualTeacher!=null,"No applicable primary teacher. Assign one or select an eligible teacher.");
   boolean assigned=db.queryForObject("select count(*) from teacher_assignments where offering_id=? and teacher_id=? and not legacy and effective_from<=? and (effective_to is null or effective_to>=?) and effective_from<=current_date and (effective_to is null or effective_to>=current_date)",Integer.class,offeringId,actualTeacher,x.date(),x.date())>0;
   if(!assigned){check(x.authorizeSubstitute(),"Selected teacher is not assigned. Explicit substitute authorization is required.");check(db.queryForObject("select count(*) from teacher_profiles where id=? and active=true",Integer.class,actualTeacher)>0,"Active teacher profile not found");makeSubstitute=true;}
   else check(!x.authorizeSubstitute(),"Substitute authorization is only for a teacher not assigned to this offering");
  }
  UUID id=UUID.randomUUID();
  try{db.update("insert into sessions(id,course_id,offering_id,teacher_profile_id,class_date,class_start_time,class_end_time) values(?,?,?,?,?,?,?)",id,offering.get("course_id"),offeringId,actualTeacher,x.date(),x.startTime(),x.endTime());}
  catch(org.springframework.dao.DataIntegrityViolationException ex){throw new ResponseStatusException(HttpStatus.CONFLICT,"An identical session already exists for this offering and time");}
  if(makeSubstitute)db.update("insert into session_substitute_authorizations(id,session_id,teacher_id,authorized_by) values(?,?,?,?)",UUID.randomUUID(),id,actualTeacher,a.getName());
  db.update("insert into attendance(session_id,student_id,student_name,roll) select ?,s.id,s.name,s.roll from offering_enrollments e join students s on s.id=e.student_id where e.offering_id=? and e.status='ACTIVE' and s.archived=false",id,offeringId);
  audit(id,a,"CREATED");
  boolean overlap=db.queryForObject("select count(*)>0 from sessions where id<>? and offering_id=? and teacher_profile_id=? and class_date=? and class_start_time<? and class_end_time>?",Boolean.class,id,offeringId,actualTeacher,x.date(),x.endTime(),x.startTime());
  return Map.of("id",id,"overlapWarning",overlap);
 }
 @GetMapping("/sessions/{id}") @Transactional Object get(@PathVariable UUID id,Authentication a){var s=session(id,a);return Map.of("session",s,"roster",db.queryForList("select * from attendance where session_id=? order by roll",id),"audit",db.queryForList("select * from audit where session_id=? order by id",id));}
 @Transactional @DeleteMapping("/sessions/{id}") Object deleteSession(@PathVariable UUID id,Authentication a){adminOnly(a);var s=db.queryForMap("select * from sessions where id=? for update",id);check(!"FINALIZED".equals(s.get("status")),"Finalized sessions cannot be deleted.");db.update("delete from attendance where session_id=?",id);db.update("delete from session_substitute_authorizations where session_id=?",id);db.update("delete from audit where session_id=?",id);adminDeletion("SESSION",id,a,"DELETED");db.update("delete from sessions where id=?",id);return Map.of("deleted",true);}
 record Edit(int version,Map<UUID,String> states,Map<UUID,String> sources){}
 @Transactional @DeleteMapping("/sessions/{id}/substitute/{teacherId}") Object revokeSubstitute(@PathVariable UUID id,@PathVariable UUID teacherId,Authentication a){adminOnly(a);var s=db.queryForMap("select id,status from sessions where id=? for update",id);draft(s);int updated=db.update("update session_substitute_authorizations set revoked_at=now() where session_id=? and teacher_id=? and revoked_at is null",id,teacherId);check(updated==1,"Active substitute authorization not found");audit(id,a,"SUBSTITUTE_REVOKED "+teacherId);return Map.of("revoked",true);}
 @PutMapping("/sessions/{id}") @Transactional Object save(@PathVariable UUID id,@RequestBody Edit x,Authentication a){var s=session(id,a);draft(s);check(((Number)s.get("version")).intValue()==x.version(),"Draft changed. Reload before saving.");for(var e:x.states().entrySet()){check(Set.of("PRESENT","ABSENT","UNCONFIRMED").contains(e.getValue()),"Invalid state");String source=x.sources()==null?"MANUAL":x.sources().getOrDefault(e.getKey(),"MANUAL");check(Set.of("NONE","AI","MANUAL").contains(source),"Invalid decision source");check(db.update("update attendance set state=?,decision_source=? where session_id=? and student_id=?",e.getValue(),source,id,e.getKey())==1,"Student outside roster");}db.update("update sessions set version=version+1,status='IN_REVIEW' where id=?",id);audit(id,a,"DRAFT_SAVED "+x.states());return get(id,a);}
 @PostMapping("/sessions/{id}/confirm") @Transactional Object confirm(@PathVariable UUID id,@RequestBody Map<String,Integer> x,Authentication a){var s=session(id,a);if(s.get("status").equals("FINALIZED"))return get(id,a);check(Objects.equals(s.get("version"),x.get("version")),"Draft changed. Reload.");check(db.queryForObject("select count(*) from attendance where session_id=?",Integer.class,id)>0,"Empty roster");check(db.queryForObject("select count(*) from attendance where session_id=? and state='UNCONFIRMED'",Integer.class,id)==0,"Review every student first");db.update("update sessions set status='FINALIZED',version=version+1 where id=?",id);audit(id,a,"FINALIZED");return get(id,a);}
 @PostMapping("/sessions/{id}/recognize") @Transactional Object recognize(@PathVariable UUID id,@RequestParam("images") List<MultipartFile> files,Authentication a)throws Exception{var s=session(id,a);draft(s);check(files.size()>=1&&files.size()<=3,"Upload 1–3 photos");var ids=db.queryForList("select a.student_id from attendance a join students s on s.id=a.student_id where a.session_id=? and s.consent=true",UUID.class,id);var body=new LinkedMultiValueMap<String,Object>();body.add("studentIds",String.join(",",ids.stream().map(UUID::toString).toList()));for(var f:files)body.add("images",resource(f));return ai().post().uri("/recognize").contentType(MediaType.MULTIPART_FORM_DATA).body(body).retrieve().body(Map.class);}
 @GetMapping(value="/reports.csv",produces="text/csv") Object report(Authentication a){var rows=admin(a)?db.queryForList("select c.name,a.roll,a.student_name,count(*) total,count(*) filter(where a.state='PRESENT') present from attendance a join sessions s on s.id=a.session_id join courses c on c.id=s.course_id where s.status='FINALIZED' group by c.name,a.roll,a.student_name"):db.queryForList("select c.name,a.roll,a.student_name,count(*) total,count(*) filter(where a.state='PRESENT') present from attendance a join sessions s on s.id=a.session_id join courses c on c.id=s.course_id where s.status='FINALIZED' and c.teacher=? group by c.name,a.roll,a.student_name",a.getName());var out=new StringBuilder("Course,Roll,Name,Finalized sessions,Present,Percentage\n");for(var row:rows){for(String k:List.of("name","roll","student_name","total","present"))out.append(csv(row.get(k))).append(',');out.append(100.0*((Number)row.get("present")).doubleValue()/((Number)row.get("total")).doubleValue()).append('\n');}return out.toString();}
 String csv(Object x){String v=String.valueOf(x);if(v.matches("^[=+@-].*"))v="'"+v;return "\""+v.replace("\"","\"\"")+"\"";}
 ByteArrayResource resource(MultipartFile f)throws Exception{check(f.getSize()>0&&f.getSize()<=10485760,"Invalid image size");return new ByteArrayResource(f.getBytes()){@Override public String getFilename(){return "upload.jpg";}};}
 RestClient ai(){return RestClient.builder().baseUrl(System.getenv().getOrDefault("AI_URL","http://localhost:8001")).defaultHeader("X-Service-Key",System.getenv("AI_SERVICE_KEY")).build();}
}
